const subtitleDialog=document.createElement('dialog');subtitleDialog.id='subtitleDialog';subtitleDialog.className='work-dialog';subtitleDialog.style.width='min(850px,94vw)';document.body.append(subtitleDialog);
const speechDialog=document.createElement('dialog');speechDialog.id='speechDialog';speechDialog.className='work-dialog';document.body.append(speechDialog);
const subtitleStyle=document.createElement('style');subtitleStyle.textContent='.clip.subtitle{background:#6753a7;color:#fff;border:1px solid #c8aeff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:8px}.subtitle-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:9999}#subtitleDialog textarea{width:100%;min-height:90px;box-sizing:border-box;background:#07192f;color:white}#subtitleDialog .sub-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}#subtitleDialog canvas{width:100%;max-width:480px;background:#030b16}#subtitleDialog input,#subtitleDialog select{max-width:190px}';document.head.append(subtitleStyle);
const subtitleOverlay=document.createElement('canvas');subtitleOverlay.className='subtitle-overlay';$('.monitor-screen').append(subtitleOverlay);
const cleanMonitor=document.createElement('style');cleanMonitor.textContent='.monitor-screen::before,.monitor-screen::after,.monitor-screen .frame-label{display:none}';document.head.append(cleanMonitor);
function subtitleCues(seconds=null){return timelineClips().filter(c=>c.dataset.kind==='subtitle'&&c.dataset.mute!=='true'&&trackIsEnabled(c.parentElement)&&(seconds===null||clipIsActiveAt(c,seconds))).map(c=>({...clipTiming(c),subtitleText:c.dataset.subtitleText||c.firstChild.textContent,subtitleStyle:JSON.parse(c.dataset.subtitleStyle||'{}'),opacity:Number(c.dataset.gain??1)*Number(c.parentElement.dataset.gain??1)*envelopeValue(c.parentElement,seconds??0)}));}
function subtitleSelection(){const clip=selectedTimelineClip;$('.panel-title span',$('.inspector')).textContent=clip?.parentElement?.dataset.track||'—';if(clip?.isConnected){$('#selectedName').textContent=clip.dataset.kind==='subtitle'?'Subtítulo':clip.firstChild?.textContent||'Evento';const t=clipTiming(clip);$('#selectedMeta').textContent=`${clip.parentElement.dataset.track} · ${t.startSeconds.toFixed(3)} s · ${t.durationSeconds.toFixed(3)} s`;}else{$('#selectedName').textContent='Sin evento seleccionado';$('#selectedMeta').textContent='Selecciona un elemento en la timeline';}}
window.LQTACSubtitles={selection:subtitleSelection,draw:(ctx,w,h,t)=>{if($('#renderSubtitles')?.checked!==false)LQTACSubtitleModel.draw(ctx,w,h,subtitleCues(t));},render(t,size){const rect=$('.monitor-screen').getBoundingClientRect(),w=size?.width||Math.max(2,Math.round(rect.width)),h=size?.height||Math.max(2,Math.round(rect.height));if(subtitleOverlay.width!==w)subtitleOverlay.width=w;if(subtitleOverlay.height!==h)subtitleOverlay.height=h;const ctx=subtitleOverlay.getContext('2d');ctx.clearRect(0,0,w,h);LQTACSubtitleModel.draw(ctx,w,h,subtitleCues(t));}};
function addSubtitleCues(cues,name='Subtítulos'){if(!cues.length){toast('No se ha detectado voz');return null;}if(timelineClips().length+cues.length>10000)throw Error('Máximo de 10000 eventos por proyecto');for(const c of cues){LQTACSubtitleModel.validate(c);if(!Number.isFinite(c.startSeconds)||c.startSeconds<0||!Number.isFinite(c.durationSeconds)||c.durationSeconds<=0||c.startSeconds+c.durationSeconds>604800)throw Error('Tiempos de subtítulo no válidos');}if($$('.track').length>=200)throw Error('Máximo de 200 pistas');historyCheckpoint();historyMuted++;let track;try{track=addTimelineTrack('subtitle');$$('#trackLabels .track-label strong').at(-1).textContent=name;for(const cue of cues)createTimelineClip(track,{...cue,kind:'subtitle',name:cue.subtitleText,filePath:'',autoCrossfade:false},cue.startSeconds/timelineDurationSeconds*100);refreshTimelineScale();}finally{historyMuted--;}applyTimelineSelection(timelineClips().filter(c=>c.parentElement===track));void renderTimelineAt(timelineTime);return track;}
function addManualSubtitle(){if(exporting||historyBusy)return;let track=$$('.track').find(t=>t.dataset.kind==='subtitle'),clip;historyCheckpoint();historyMuted++;try{if(!track)track=addTimelineTrack('subtitle');clip=createTimelineClip(track,{startSeconds:timelineTime,durationSeconds:3,subtitleText:'Nuevo subtítulo',name:'Nuevo subtítulo',kind:'subtitle',filePath:'',autoCrossfade:false},timelineTime/timelineDurationSeconds*100);refreshTimelineScale();}finally{historyMuted--;}if(clip)openSubtitleEditor(clip);}
function openSubtitleEditor(clip){if(!clip?.isConnected||clip.dataset.kind!=='subtitle'||subtitleDialog.open||exporting||historyBusy)return;stopTimelinePlayback();selectTimelineClip(clip);const timing=clipTiming(clip),style=LQTACSubtitleModel.style(JSON.parse(clip.dataset.subtitleStyle||'{}'));
  subtitleDialog.innerHTML='<form><h2>Editar subtítulo</h2><textarea id="subText" maxlength="10000" required aria-label="Texto del subtítulo"></textarea><div class="sub-grid"><label>Inicio (s)<input id="subStart" type="number" min="0" max="604800" step="0.001" required></label><label>Duración (s)<input id="subDuration" type="number" min="0.042" max="604800" step="0.001" required></label><label>Tipografía<select id="subFont"><option>Segoe UI</option><option>Arial</option><option>Verdana</option><option>Georgia</option></select></label><label>Tamaño (referencia 720p)<input id="subSize" type="number" min="12" max="96" required></label><label>Color<input id="subColor" type="color"></label><label>Contorno<input id="subOutline" type="color"></label><label>Grosor del contorno<input id="subStroke" type="number" min="0" max="10" step="0.5" required></label><label>Posición X (0–1)<input id="subX" type="number" min="0" max="1" step="0.01" required></label><label>Posición Y (0–1)<input id="subY" type="number" min="0" max="1" step="0.01" required></label></div><canvas id="subPreview" width="480" height="270"></canvas><p>El estilo se aplica a este bloque. SRT conserva texto y tiempos, no tipografía ni colores.</p><p id="subError" role="alert"></p><footer><button type="button" id="subDelete">Eliminar bloque</button><button type="button" id="subCancel">Cancelar</button><button type="submit">Aplicar</button></footer></form>';
  $('#subText').value=clip.dataset.subtitleText;$('#subStart').value=timing.startSeconds;$('#subDuration').value=timing.durationSeconds;for(const [id,k] of [['subFont','font'],['subSize','size'],['subColor','color'],['subOutline','outline'],['subStroke','stroke'],['subX','x'],['subY','y']])$('#'+id).value=style[k];
  const value=()=>({subtitleText:$('#subText').value.trim(),subtitleStyle:{font:$('#subFont').value,size:Number($('#subSize').value),color:$('#subColor').value,outline:$('#subOutline').value,stroke:Number($('#subStroke').value),x:Number($('#subX').value),y:Number($('#subY').value)}});
  const preview=()=>{try{const cue=value();LQTACSubtitleModel.validate(cue);const ctx=$('#subPreview').getContext('2d');ctx.fillStyle='#07192f';ctx.fillRect(0,0,480,270);LQTACSubtitleModel.draw(ctx,480,270,[cue]);}catch{}};subtitleDialog.oninput=preview;subtitleDialog.onkeydown=e=>e.stopPropagation();
  $('form',subtitleDialog).onsubmit=e=>{e.preventDefault();try{const cue=value(),start=Number($('#subStart').value),duration=Number($('#subDuration').value);LQTACSubtitleModel.validate(cue);if(!clip.isConnected||!Number.isFinite(start)||start<0||!Number.isFinite(duration)||duration<=0||start+duration>604800)throw Error('Tiempos no válidos');historyCheckpoint();clip.dataset.subtitleText=cue.subtitleText;clip.firstChild.textContent=cue.subtitleText;clip.dataset.subtitleStyle=JSON.stringify(cue.subtitleStyle);clip.dataset.startSeconds=String(start);clip.dataset.durationSeconds=String(duration);clip.dataset.sourceOffsetSeconds='0';delete clip.dataset.sourceDurationSeconds;refreshTimelineScale();subtitleDialog.close();subtitleSelection();void renderTimelineAt(timelineTime);}catch(error){$('#subError').textContent=error.message;}};
  $('#subDelete').onclick=()=>{subtitleDialog.close();removeTimelineClip(clip);};$('#subCancel').onclick=()=>subtitleDialog.close();subtitleDialog.showModal();preview();
}
async function openSubtitleGeneration(){if(exporting||historyBusy||speechDialog.open)return;stopTimelinePlayback();const project=projectSnapshot(),sources=[];project.tracks.forEach((t,i)=>{if(!t.clips.some(c=>c.kind==='audio'&&c.filePath))return;sources.push({value:i+':all',name:'Pista · '+t.name});t.clips.forEach((c,j)=>{if(c.kind==='audio'&&c.filePath)sources.push({value:i+':'+j,name:'Clip · '+c.name});});});if(!sources.length){toast('Importa un vídeo con audio o una pista de voz');return;}
  speechDialog.innerHTML='<h2>Generar subtítulos · Whisper local</h2><label>Audio a analizar<select id="speechSource"></select></label><label>Idioma<select id="speechLanguage"><option value="es">Español</option><option value="auto">Detectar automáticamente</option><option value="en">Inglés</option><option value="fr">Francés</option><option value="de">Alemán</option><option value="it">Italiano</option><option value="pt">Portugués</option><option value="ca">Catalán</option><option value="eu">Euskera</option><option value="gl">Gallego</option></select></label><p>Procesamiento en este equipo, sin enviar audio. Se analiza el origen elegido aunque esté silenciado. Para voces con música, elige la pista de voz si está disponible. Se crea una nueva pista; revisa texto y tiempos.</p><p id="speechStatus" role="status">Comprobando motor…</p><progress id="speechProgress" max="1" value="0"></progress><footer><button id="speechClose" type="button">Cerrar</button><button id="speechRun" type="button" disabled>Generar pista de subtítulos</button></footer>';
  for(const source of sources){const o=document.createElement('option');o.value=source.value;o.textContent=source.name;$('#speechSource').append(o);}const selected=selectedTimelineClips.find(c=>c.dataset.kind==='audio');if(selected){const i=$$('.track').indexOf(selected.parentElement),j=timelineClips().filter(c=>c.parentElement===selected.parentElement).indexOf(selected);$('#speechSource').value=i+':'+j;}
  let busy=false,cancelled=false;const cancel=()=>{cancelled=true;void window.lqtacDesktop.cancelSubtitles();$('#speechStatus').textContent='Cancelando…';};speechDialog.oncancel=e=>{if(busy){e.preventDefault();cancel();}};$('#speechClose').onclick=()=>busy?cancel():speechDialog.close();speechDialog.showModal();
  try{const status=await window.lqtacDesktop.subtitleStatus();$('#speechStatus').textContent=status.ready?status.name:'Motor/modelo no instalado: ejecuta tools/setup-whisper.ps1 en el equipo de desarrollo o utiliza el portable con modelo incluido.';$('#speechRun').disabled=!status.ready;}catch(e){$('#speechStatus').textContent=e.message;}
  $('#speechRun').onclick=async()=>{if(busy)return;busy=true;cancelled=false;$('.workspace').inert=true;$('#speechRun').disabled=true;$('#speechSource').disabled=$('#speechLanguage').disabled=true;$('#speechClose').textContent='Cancelar';const unsubscribe=window.lqtacDesktop.onSubtitleProgress(p=>{$('#speechStatus').textContent=p.stage;$('#speechProgress').value=p.progress||0;});
    try{const [track,clip]=$('#speechSource').value.split(':'),result=await window.lqtacDesktop.transcribeSubtitles({project,trackIndex:Number(track),clipIndex:clip==='all'?null:Number(clip),language:$('#speechLanguage').value});if(!cancelled){addSubtitleCues(result.cues,'Subtítulos · '+$('#speechLanguage').selectedOptions[0].textContent);$('#speechStatus').textContent=result.cues.length+' bloques creados. Revisa el texto y la sincronización.';$('#speechProgress').value=1;}}catch(e){$('#speechStatus').textContent=e.message;}finally{unsubscribe();busy=false;$('.workspace').inert=false;$('#speechRun').disabled=false;$('#speechSource').disabled=$('#speechLanguage').disabled=false;$('#speechClose').textContent='Cerrar';}
  };
}
const subtitleBox=$('.ai-box');subtitleBox.innerHTML='<h3>Subtítulos · motor local</h3><p>Genera una pista editable desde voz. Sin conexión y sin enviar archivos.</p><button id="generateSubtitles" type="button" class="solid-btn">Generar subtítulos</button><button id="addSubtitle" type="button" class="ghost-btn">Añadir subtítulo</button><button id="importSrt" type="button" class="ghost-btn">Importar SRT</button><button id="exportSrt" type="button" class="ghost-btn">Exportar SRT</button>';
$('#generateSubtitles').onclick=()=>void openSubtitleGeneration();$('#addSubtitle').onclick=addManualSubtitle;$('#importSrt').onclick=async()=>{try{const cues=await window.lqtacDesktop.importSubtitles();if(cues)addSubtitleCues(cues,'Subtítulos importados');}catch(e){alert(e.message);}};$('#exportSrt').onclick=async()=>{try{const cues=subtitleCues();if(!cues.length){toast('No hay subtítulos habilitados para exportar');return;}const p=await window.lqtacDesktop.exportSubtitles(cues);if(p)toast('SRT guardado · '+p);}catch(e){alert(e.message);}};
