subtitleDock.onclick=()=>{$$('.dock-panel-item').forEach(b=>b.classList.toggle('active',b===subtitleDock));[...$('.side-panel').children].forEach(c=>c.hidden=c!==subtitlePanel);stopTransitionPreview();};
