const projectPanel=document.createElement('section');projectPanel.hidden=true;projectPanel.id='projectInfoPanel';projectPanel.innerHTML='<h2>Información del proyecto</h2><p id="projectInfoSummary"></p>';projectPanel.append($('.compat-box'),$('#openVegasReport'));$('.side-panel').append(projectPanel);$('.compat-list',projectPanel).textContent='LQTS · VEG mediante puente VEGAS';$('p',$('.compat-box')).textContent='La conversión inicial requiere VEGAS Pro instalado si no existe un puente válido. Consulta el informe de importación para conocer sus límites.';
const projectDock=document.createElement('button');projectDock.type='button';projectDock.className='dock-panel-item';projectDock.innerHTML='<span>ⓘ</span><strong>Proyecto</strong>';$('.dock-panel-list').append(projectDock);projectDock.onclick=()=>{$$('.dock-panel-item').forEach(b=>b.classList.toggle('active',b===projectDock));[...$('.side-panel').children].forEach(c=>c.hidden=c!==projectPanel);$('#projectInfoSummary').textContent=`${$('#projectName').textContent} · ${$$('.track').length} pistas · ${timelineClips().length} eventos`;stopTransitionPreview();};
$$('.dock-panel-item').filter(b=>b!==projectDock).forEach(b=>b.addEventListener('click',()=>projectPanel.hidden=true));
